-- | |__| (_) | | | | | | |  __/ (__| |_| | (_) | | | \__ \ |  __/ (_) | | | (__| |  __/\__ \
--  \____\___/|_| |_|_| |_|\___|\___|\__|_|\___/|_| |_|___/ |_|   \___/|_|_|\___|_|\___||___/
alter table "public"."connection" enable row level security;
revoke
insert,
    update,
    delete on table "public"."connection"
from anon,
    authenticated;
create policy "Enable read access for all users" on "public"."connection" as PERMISSIVE for
SELECT to authenticated,
    anon using (true);
