-- | |_) | '__/ _ \| __| |_ / _ \| | |/ _ \  | |_) / _ \| | |/ __| |/ _ \/ __|
-- |  __/| | | (_) | |_|  _| (_) | | | (_) | |  __/ (_) | | | (__| |  __/\__ \
-- |_|   |_|  \___/ \__|_|  \___/|_|_|\___/  |_|   \___/|_|_|\___|_|\___||___/
alter table public.portfolio replica identity full;
alter table "public"."portfolio" enable row level security;
create policy "Enable users to view their own data only" on "public"."portfolio" as PERMISSIVE for
SELECT to authenticated using (
        (
            select auth.uid()
        ) = user_id
    );
create policy "Enable insert for users based on user_id" on "public"."portfolio" as PERMISSIVE for
INSERT to authenticated with check (
        (
            select auth.uid()
        ) = user_id
    );
create policy "Enable delete for users based on user_id" on "public"."portfolio" as PERMISSIVE for DELETE to authenticated using (
    (
        select auth.uid()
    ) = user_id
);
create policy "Enable update for users based on user_id" on "public"."portfolio" as PERMISSIVE for
UPDATE to authenticated using (
        (
            select auth.uid()
        ) = user_id
    );
alter publication supabase_realtime
add table portfolio;